import {
  handleAppCacheRequest,
  hasAppCachePath,
  initAppCachePaths,
} from "./modules/app-cache-handle.js";
import {
  handleGitHubRequest,
  handleNpmRequest,
  handleNcompRequest,
} from "./modules/cache-handlers.js";
import { handleFileRequest } from "./modules/file-handler.js";
import { handleMountRequest } from "./modules/mount-handle.js";
import { handleNosRequest } from "./modules/nos-handle.js";
import { handleNosToolRequest } from "./modules/nostool-handle.js";

// 当前系统的配置信息
// let systemConfig = {"version":"4.0.0","mode":"online","nosMapPath":"nos-4.0.0"};
let systemConfig = {};

const NONEOS_CORE_VERSION = "noneos-core@4.2.9";

self.addEventListener("fetch", (event) => {
  const { request } = event;
  const { pathname, hostname } = new URL(request.url);

  const coreHostName =
    globalThis?.SERVER_OPTIONS?.coreHostName || "core.noneos.com";

  if (hostname !== location.hostname && hostname !== coreHostName) {
    return;
  }

  if (pathname === "/__config") {
    return event.respondWith(reloadSystemConfig());
  }

  try {
    if (/^\/nos-tool\//.test(pathname)) {
      return event.respondWith(
        handleNosToolRequest({
          path: pathname,
          request,
          systemConfig,
        }),
      );
    }

    if (/^\/ncomp\//.test(pathname)) {
      return event.respondWith(
        handleNcompRequest({
          path: pathname,
          request,
          systemConfig,
        }),
      );
    }

    if (/^\/nos\//.test(pathname)) {
      return event.respondWith(
        handleNosRequest({
          path: pathname,
          request,
          systemConfig,
        }),
      );
    }

    if (/^\/gh\//.test(pathname)) {
      // 从 GitHub 仓库获取文件
      return event.respondWith(
        handleGitHubRequest({
          path: pathname,
          originUrl: request.url,
          systemConfig,
        }),
      );
    }

    if (/^\/npm\//.test(pathname)) {
      // 从 NPM CDN 获取包文件
      return event.respondWith(
        handleNpmRequest({
          path: pathname,
          originUrl: request.url,
          systemConfig,
        }),
      );
    }

    if (/^\/\$mount-/.test(pathname)) {
      return event.respondWith(
        handleMountRequest({
          path: pathname,
          originUrl: request.url,
          systemConfig,
        }),
      );
    }

    if (/^\/\$/.test(pathname)) {
      return event.respondWith(
        handleFileRequest({
          path: pathname,
          originUrl: request.url,
          systemConfig,
        }),
      );
    }

    // 应用缓存兜底：命中已缓存的宿主项目文件时，从 OPFS 返回
    if (request.method === "GET" && hasAppCachePath(pathname)) {
      return event.respondWith(handleAppCacheRequest({ path: pathname }));
    }
  } catch (err) {
    return new Response(err.stack || err.toString(), {
      status: 400,
    });
  }

  // if (/^\/_/.test(pathname)) {
  //   // 隐藏目录开头的，属于本地文件，无需代理
  //   return;
  // }
});

self.addEventListener("install", () => {
  self.skipWaiting();
  console.log("NoneOS installation successful");
});

self.addEventListener("activate", () => {
  self.clients.claim();
  console.log("NoneOS server activation successful");

  setTimeout(() => {
    reloadSystemConfig();
    initAppCachePaths();
  }, 1000);
});

const reloadSystemConfig = async () => {
  try {
    const rootHandle = await navigator.storage.getDirectory();
    const configHandle = await rootHandle.getDirectoryHandle("nos-config");
    const configFileHandle = await configHandle.getFileHandle("system.json");
    const file = await configFileHandle.getFile();
    const content = await file.text();

    if (content) {
      systemConfig = JSON.parse(content);
    }

    // 刷新应用缓存路径集合
    await initAppCachePaths();

    return new Response(
      JSON.stringify({
        serviceWorkerVersion: NONEOS_CORE_VERSION.replace("noneos-core@", ""),
        systemConfig,
        appCacheConfig: globalThis.NONEOS_APP_CACHE || null,
      }),
    );
  } catch (err) {
    console.error("Reload system config failed:", err);
    return new Response("Reload failed: " + (err.message || err), {
      status: 500,
    });
  }
};

reloadSystemConfig();
